{"root":{"children":[{"type":"html","version":1,"html":"<style>
#hmt-radar{--verde:#00a859;--verde-esc:#0a2e1f;--acao:#087443;--acao-tx:#fff;--s1:#2a78d6;--s2:#eb6834;--s3:#1baf7a;--sol-bg:#e8f1fc;--pol-bg:#fdefe8;--card:#f6f8f7;--campo:#fff;--tx:#111;--tx2:#3f4a45;--mu:#5b6762;--bd:#d9e2dd;--bd-ctl:#7d8c85;--grade:#e3e9e5;--base:#b9c6bf;--apag:#cdd6d1;--foco:#0b7a45;--som:0 1px 2px rgba(10,46,31,.06),0 6px 18px rgba(10,46,31,.06);position:relative;font-family:var(--font-sans,Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif);color:var(--tx);font-size:16px;line-height:1.45}
@media (prefers-color-scheme:dark){html:not([data-theme="light"]) #hmt-radar{--s1:#3987e5;--s2:#d95926;--s3:#199e70;--sol-bg:#16263b;--pol-bg:#3a2217;--card:#17201b;--campo:#0f1512;--tx:#eef3f0;--tx2:#c9d6cf;--mu:#a3b3ac;--bd:#2b3731;--bd-ctl:#627369;--grade:#26312b;--base:#3d4a43;--apag:#35423b;--foco:#5fe3a1;--acao:#3ddc84;--acao-tx:#04150c;--som:none}}
html[data-theme="dark"] #hmt-radar,html.dark #hmt-radar,body.dark-mode #hmt-radar{--s1:#3987e5;--s2:#d95926;--s3:#199e70;--sol-bg:#16263b;--pol-bg:#3a2217;--card:#17201b;--campo:#0f1512;--tx:#eef3f0;--tx2:#c9d6cf;--mu:#a3b3ac;--bd:#2b3731;--bd-ctl:#627369;--grade:#26312b;--base:#3d4a43;--apag:#35423b;--foco:#5fe3a1;--acao:#3ddc84;--acao-tx:#04150c;--som:none}
#hmt-radar *{box-sizing:border-box}
#hmt-radar :focus-visible{outline:3px solid var(--foco);outline-offset:2px}
#hmt-radar .rd-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;border:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
#hmt-radar h2,#hmt-radar h3,#hmt-radar h4,#hmt-radar h5{font-family:inherit;letter-spacing:0}
#hmt-radar .rd-col a{font-family:var(--font-serif,"Source Serif 4",Georgia,"Times New Roman",serif)}
#hmt-radar figure{margin:0}
#hmt-radar button{font-family:inherit}
/* Topo */
#hmt-radar .rd-topo{background:radial-gradient(120% 140% at 100% 0,#16704a 0,rgba(22,112,74,0) 55%),linear-gradient(135deg,var(--verde-esc),#0f4a33);color:#fff;border-radius:18px;padding:22px 22px 18px;margin:0 0 14px;overflow:hidden}
#hmt-radar .rd-kicker{font-size:.72rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:#7ff0b8;margin:0 0 6px}
#hmt-radar .rd-topo h2{margin:0 0 6px;font-size:1.55rem;line-height:1.15;color:#fff}
#hmt-radar .rd-topo p{margin:0;color:#d4ebe0;font-size:.95rem;max-width:60ch}
#hmt-radar .rd-status{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px;font-size:.84rem}
#hmt-radar .rd-status span{background:rgba(255,255,255,.12);border-radius:999px;padding:4px 11px}
#hmt-radar .rd-status .rd-cd{background:#7ff0b8;color:#06301d;font-weight:800}
@media (max-width:600px){#hmt-radar .rd-topo{padding:18px 16px 14px}#hmt-radar .rd-topo h2{font-size:1.3rem}#hmt-radar .rd-topo p{font-size:.9rem}#hmt-radar .rd-status .rd-opc{display:none}#hmt-radar .rd-grupo button{padding:6px 10px;font-size:.84rem;min-height:34px}#hmt-radar .rd-filtros{padding:12px;gap:10px}#hmt-radar .rd-rot{min-width:0;width:100%}}
#hmt-radar .rd-novas{margin-top:10px;font-size:.86rem;color:#eafff4}
#hmt-radar .rd-vivo{display:inline-flex;align-items:center;gap:6px;font-weight:700}
#hmt-radar .rd-vivo i{width:8px;height:8px;border-radius:50%;background:#7ff0b8;box-shadow:0 0 0 0 rgba(127,240,184,.7)}
#hmt-radar .rd-vivo.off i{background:#b9c6bf}
@media (prefers-reduced-motion:no-preference){#hmt-radar .rd-vivo:not(.off) i{animation:rd-pulso 2s infinite}#hmt-radar li.rd-chegou{animation:rd-chega 4s ease-out}}
@keyframes rd-pulso{0%{box-shadow:0 0 0 0 rgba(127,240,184,.7)}70%{box-shadow:0 0 0 8px rgba(127,240,184,0)}100%{box-shadow:0 0 0 0 rgba(127,240,184,0)}}
@keyframes rd-chega{0%{background:rgba(0,168,89,.22)}100%{background:transparent}}
#hmt-radar .rd-toast{position:fixed;z-index:50;right:16px;bottom:16px;max-width:min(420px,calc(100vw - 32px));display:flex;align-items:center;gap:10px;background:var(--verde-esc);color:#fff;border-radius:14px;padding:10px 10px 10px 14px;font-size:.88rem;box-shadow:0 10px 30px rgba(0,0,0,.3)}
#hmt-radar .rd-toast[hidden]{display:none}
#hmt-radar .rd-toast span{flex:1;min-width:0}
#hmt-radar .rd-toast button{border:0;border-radius:999px;background:#7ff0b8;color:#06301d;font-weight:800;padding:6px 14px;cursor:pointer;min-height:34px}
#hmt-radar .rd-toast .rd-x{background:transparent;color:#fff;font-size:1.2rem;padding:4px 8px;font-weight:400}
@media (max-width:600px){#hmt-radar .rd-toast{left:16px;right:16px;max-width:none}}
#hmt-radar .rd-novas b{background:#fff;color:#0a2e1f;border-radius:999px;padding:1px 8px;margin-right:4px}
/* Filtros */
#hmt-radar .rd-filtros{border:1px solid var(--bd);border-radius:14px;background:var(--card);padding:14px;margin:0 0 12px;display:grid;gap:12px;scroll-margin-top:96px}
#hmt-radar .rd-filtros[hidden]{display:none}
#hmt-radar .rd-linha{display:flex;flex-wrap:wrap;gap:8px 14px;align-items:center}
#hmt-radar .rd-rot{font-size:.76rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--mu);min-width:64px}
#hmt-radar .rd-grupo{display:flex;flex-wrap:wrap;gap:6px;position:relative}
#hmt-radar .rd-grupo button{border:1px solid var(--bd-ctl);background:transparent;color:var(--tx);border-radius:999px;padding:7px 13px;font-size:.88rem;cursor:pointer;min-height:36px}
#hmt-radar .rd-grupo button:hover{border-color:var(--verde)}
#hmt-radar .rd-grupo button[aria-checked="true"]{background:var(--acao);border-color:var(--acao);color:var(--acao-tx);font-weight:700}
#hmt-radar .rd-grupo button small{opacity:.75;margin-left:4px;font-size:.78rem}
#hmt-radar .rd-grupo button[aria-checked="true"] small{opacity:1}
#hmt-radar .rd-grupo button[aria-disabled="true"]{opacity:.45;cursor:default;border-style:dashed}
#hmt-radar .rd-grupo button[aria-disabled="true"]:hover{border-color:var(--bd-ctl)}
@media (forced-colors:active){#hmt-radar .rd-grupo button[aria-checked="true"]{outline:2px solid CanvasText;outline-offset:1px}}
#hmt-radar .rd-campos{display:grid;grid-template-columns:minmax(0,1.6fr) repeat(3,minmax(0,1fr));gap:10px}
@media (max-width:640px){#hmt-radar .rd-campos{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}#hmt-radar .rd-campos .rd-busca{grid-column:1/-1}#hmt-radar .rd-campos select{padding:8px 6px;font-size:.9rem}}
#hmt-radar .rd-campos label{display:grid;gap:4px;font-size:.76rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--mu)}
#hmt-radar .rd-campos input,#hmt-radar .rd-campos select{font:inherit;font-size:.95rem;text-transform:none;letter-spacing:0;font-weight:400;color:var(--tx);background:var(--campo);border:1px solid var(--bd-ctl);border-radius:10px;padding:8px 10px;min-height:40px;width:100%}
#hmt-radar .rd-leia{font-size:.86rem;color:var(--mu);margin:0 0 12px;display:flex;flex-wrap:wrap;gap:4px 14px;align-items:center}
#hmt-radar .rd-pt{display:inline-block;width:10px;height:10px;border-radius:3px;vertical-align:-1px;margin-right:5px}
#hmt-radar .rd-pt.p{background:var(--s2)}#hmt-radar .rd-pt.s{background:var(--s1)}
/* Painel */
#hmt-radar .rd-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px;margin:0 0 12px}
#hmt-radar .rd-kpi{background:var(--card);border:1px solid var(--bd);border-radius:14px;padding:12px 14px;box-shadow:var(--som)}
#hmt-radar .rd-kpi b{display:block;font-size:1.7rem;line-height:1.1;font-weight:750;color:var(--tx)}
#hmt-radar .rd-kpi span{display:flex;align-items:center;font-size:.8rem;color:var(--mu);margin-top:3px}
@media (max-width:600px){#hmt-radar .rd-kpis{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}#hmt-radar .rd-kpi{padding:9px 10px;border-radius:12px}#hmt-radar .rd-kpi b{font-size:1.3rem}#hmt-radar .rd-kpi span{font-size:.74rem;line-height:1.25}}
#hmt-radar .rd-graficos{display:grid;grid-template-columns:1.25fr 1fr;gap:12px;margin:0 0 12px}
@media (max-width:760px){#hmt-radar .rd-graficos{grid-template-columns:1fr}}
#hmt-radar .rd-fig{background:var(--card);border:1px solid var(--bd);border-radius:14px;padding:14px 14px 10px;box-shadow:var(--som);min-width:0}
#hmt-radar .rd-fig+.rd-fig{margin-top:0}
#hmt-radar .rd-larga{margin:0 0 12px}
#hmt-radar .rd-fig h3{margin:0;font-size:1rem;line-height:1.25;color:var(--tx)}
#hmt-radar .rd-fig figcaption p{margin:3px 0 8px;font-size:.82rem;color:var(--mu)}
#hmt-radar .rd-leg{display:flex;flex-wrap:wrap;gap:4px 14px;font-size:.8rem;color:var(--tx2);margin:0 0 6px}
#hmt-radar .rd-leg span{display:inline-flex;align-items:center}
#hmt-radar .rd-plot svg{display:block;width:100%;height:auto;overflow:visible}
#hmt-radar .rd-plot text{font-family:inherit;fill:var(--mu);font-size:11px}
#hmt-radar .rd-plot .rd-val{fill:var(--tx2);font-size:11px;font-weight:650}
#hmt-radar .rd-plot .rd-nm{fill:var(--tx);font-size:12px}
#hmt-radar .rd-plot .rd-gr{fill:var(--mu);font-size:10.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase}
#hmt-radar .rd-plot [data-tip]{cursor:pointer}
#hmt-radar .rd-plot [data-tip]:hover .rd-hl,#hmt-radar .rd-plot [data-tip]:focus-visible .rd-hl{fill:var(--grade)}
#hmt-radar .rd-plot [data-tip]:focus{outline:none}
#hmt-radar .rd-plot [data-tip]:focus-visible .rd-hl{stroke:var(--foco);stroke-width:2px}
#hmt-radar .rd-rodape-fig{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-top:6px;font-size:.78rem;color:var(--mu)}
#hmt-radar .rd-bt-tab{white-space:nowrap;flex:0 0 auto;border:0;background:none;color:var(--acao);font-size:.8rem;font-weight:700;cursor:pointer;padding:6px 0;text-decoration:underline;text-underline-offset:3px}
@media (prefers-color-scheme:dark){html:not([data-theme="light"]) #hmt-radar .rd-bt-tab{color:var(--foco)}}
html[data-theme="dark"] #hmt-radar .rd-bt-tab{color:var(--foco)}
#hmt-radar .rd-tabela{overflow-x:auto;margin-top:6px}
#hmt-radar .rd-tabela table{border-collapse:collapse;width:100%;font-size:.84rem}
#hmt-radar .rd-tabela th,#hmt-radar .rd-tabela td{border-bottom:1px solid var(--bd);padding:5px 8px;text-align:left;color:var(--tx)}
#hmt-radar .rd-tabela td.n,#hmt-radar .rd-tabela th.n{text-align:right;font-variant-numeric:tabular-nums}
#hmt-radar .rd-tip{position:absolute;z-index:5;pointer-events:none;background:var(--campo);color:var(--tx);border:1px solid var(--bd);border-radius:10px;padding:8px 10px;font-size:.82rem;box-shadow:0 8px 24px rgba(0,0,0,.18);max-width:260px}
#hmt-radar .rd-tip b{display:block;margin-bottom:2px}
#hmt-radar .rd-tip div{display:flex;align-items:center;gap:6px;white-space:nowrap}
#hmt-radar .rd-tip i{display:inline-block;width:12px;height:3px;border-radius:2px}
#hmt-radar .rd-tip .rd-tv{font-weight:750;min-width:2ch}
#hmt-radar .rd-tip .rd-tm{color:var(--mu)}
/* Resumo */
#hmt-radar .rd-resumo{display:flex;flex-wrap:wrap;justify-content:space-between;gap:8px;align-items:center;font-size:.9rem;color:var(--mu);margin:4px 0 10px}
#hmt-radar .rd-acoes{display:flex;gap:8px;flex-wrap:wrap}
#hmt-radar .rd-limpar,#hmt-radar .rd-comp{border:1px solid var(--bd-ctl);background:var(--campo);color:var(--tx);border-radius:999px;padding:6px 12px;font-size:.84rem;cursor:pointer;min-height:34px}
#hmt-radar .rd-comp{border-color:var(--acao);color:var(--acao);font-weight:700}
@media (prefers-color-scheme:dark){html:not([data-theme="light"]) #hmt-radar .rd-comp{border-color:var(--foco);color:var(--foco)}}
html[data-theme="dark"] #hmt-radar .rd-comp{border-color:var(--foco);color:var(--foco)}
#hmt-radar .rd-volta{position:sticky;top:10px;z-index:4;margin:0 0 8px auto;display:block;border:0;background:var(--acao);color:var(--acao-tx);border-radius:999px;padding:8px 14px;font-size:.85rem;font-weight:700;cursor:pointer;box-shadow:0 6px 16px rgba(0,0,0,.2);max-width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#hmt-radar .rd-volta[hidden]{display:none}
/* Cards */
#hmt-radar .rd-cargo{font-size:1.08rem;margin:20px 0 10px;display:flex;align-items:baseline;gap:8px;color:var(--tx)}
#hmt-radar .rd-cargo small{font-size:.8rem;color:var(--mu);font-weight:400}
#hmt-radar .rd-grade{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,540px),1fr));gap:12px}
#hmt-radar .rd-card{container-type:inline-size;background:var(--card);border:1px solid var(--bd);border-radius:16px;padding:14px;display:flex;flex-direction:column;gap:10px;min-width:0;box-shadow:var(--som);scroll-margin-top:90px}
#hmt-radar .rd-card:target{outline:3px solid var(--foco);outline-offset:2px}
#hmt-radar .rd-cab{display:flex;gap:10px;align-items:center}
#hmt-radar .rd-av{flex:0 0 42px;height:42px;border-radius:50%;display:grid;place-items:center;font-weight:800;font-size:.95rem;color:var(--acao);background:var(--campo);border:2px solid var(--acao)}
@media (prefers-color-scheme:dark){html:not([data-theme="light"]) #hmt-radar .rd-av{color:var(--foco);border-color:var(--foco)}}
html[data-theme="dark"] #hmt-radar .rd-av{color:var(--foco);border-color:var(--foco)}
#hmt-radar .rd-id{flex:1;min-width:0}
#hmt-radar .rd-nome{margin:0;font-size:1.05rem;line-height:1.2;color:var(--tx)}
#hmt-radar .rd-sub{font-size:.8rem;color:var(--mu);margin-top:2px}
#hmt-radar .rd-num{flex:0 0 auto;font-weight:800;font-size:.95rem;border-radius:10px;padding:4px 9px;background:var(--campo);border:1px solid var(--bd);color:var(--tx);font-variant-numeric:tabular-nums}
#hmt-radar .rd-num small{display:block;font-size:.58rem;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--mu);text-align:center}
#hmt-radar .rd-ofic{margin:0;display:flex;flex-wrap:wrap;gap:3px 18px;font-size:.8rem;border-top:1px dashed var(--bd);padding-top:8px}
#hmt-radar .rd-ofic div{display:flex;gap:6px;min-width:0}
#hmt-radar .rd-ofic dt{color:var(--mu)}#hmt-radar .rd-ofic dd{margin:0;color:var(--tx2)}
#hmt-radar .rd-chk{font-weight:700;color:var(--tx)}
#hmt-radar .rd-mini{display:grid;grid-template-columns:1fr auto;gap:10px;align-items:end}
#hmt-radar .rd-bal{display:flex;gap:2px;height:8px;border-radius:4px;overflow:hidden;background:var(--grade)}
#hmt-radar .rd-bal i{display:block;height:100%}
#hmt-radar .rd-bal i.p{background:var(--s2)}#hmt-radar .rd-bal i.s{background:var(--s1)}
#hmt-radar .rd-chips{display:flex;flex-wrap:wrap;gap:6px 12px;font-size:.82rem;color:var(--tx2);margin-top:6px}
#hmt-radar .rd-spark{display:flex;gap:2px;align-items:flex-end;height:26px}
#hmt-radar .rd-spark i{display:block;width:6px;border-radius:2px 2px 0 0;background:var(--apag);min-height:2px}
#hmt-radar .rd-spark i.h{background:var(--s3)}
#hmt-radar .rd-cols{display:grid;grid-template-columns:1fr 1fr;gap:12px}
#hmt-radar .rd-cols.uma{grid-template-columns:1fr}
@media (max-width:600px){#hmt-radar .rd-cols{grid-template-columns:1fr}}
@container (max-width:520px){#hmt-radar .rd-cols{grid-template-columns:1fr}}
#hmt-radar .rd-col{min-width:0}
#hmt-radar .rd-col-tit{margin:0 0 6px;font-size:.84rem;display:flex;flex-wrap:wrap;align-items:baseline;gap:0 5px;color:var(--tx)}
#hmt-radar .rd-col-tit small{font-weight:400;color:var(--mu)}
#hmt-radar .rd-col ul{list-style:none;margin:0;padding:0;display:grid;gap:8px}
#hmt-radar .rd-col li{border-left:3px solid var(--bd);padding:2px 0 2px 9px}
#hmt-radar .rd-col.p li{border-left-color:var(--s2)}#hmt-radar .rd-col.s li{border-left-color:var(--s1)}
#hmt-radar .rd-col li[hidden]{display:none}
#hmt-radar .rd-col a{color:var(--tx);text-decoration:none;font-size:.95rem;line-height:1.38}
#hmt-radar .rd-col a:hover{text-decoration:underline}
#hmt-radar .rd-meta{display:flex;flex-wrap:wrap;gap:4px 8px;align-items:center;font-size:.76rem;color:var(--mu);margin-top:3px}
#hmt-radar .rd-novo{background:var(--acao);color:var(--acao-tx);border-radius:999px;padding:0 7px;font-weight:800;font-size:.68rem;letter-spacing:.04em}
#hmt-radar .rd-fx summary{cursor:pointer;color:var(--mu);list-style:none}
#hmt-radar .rd-fx summary::-webkit-details-marker{display:none}
#hmt-radar .rd-fx summary::before{content:"▸ ";font-size:.7rem}
#hmt-radar .rd-fx[open] summary::before{content:"▾ "}
#hmt-radar .rd-fx p{margin:3px 0 0;color:var(--tx2)}
#hmt-radar .rd-vazio{font-size:.84rem;color:var(--mu);padding:6px 0}
#hmt-radar .rd-mais{border:0;background:none;color:var(--acao);font-size:.84rem;font-weight:700;cursor:pointer;padding:6px 0;margin-top:2px}
@media (prefers-color-scheme:dark){html:not([data-theme="light"]) #hmt-radar .rd-mais{color:var(--foco)}}
html[data-theme="dark"] #hmt-radar .rd-mais{color:var(--foco)}
#hmt-radar mark{background:#fff3a3;color:#111;border-radius:3px;padding:0 1px}
#hmt-radar .rd-rodape-card{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:.8rem;color:var(--mu);border-top:1px solid var(--bd);padding-top:8px;margin-top:auto}
#hmt-radar .rd-rodape-card a{color:var(--acao);font-weight:650}
@media (prefers-color-scheme:dark){html:not([data-theme="light"]) #hmt-radar .rd-rodape-card a{color:var(--foco)}}
html[data-theme="dark"] #hmt-radar .rd-rodape-card a{color:var(--foco)}
#hmt-radar .rd-aviso{background:var(--card);border:1px solid var(--bd);border-radius:14px;padding:18px;text-align:center;color:var(--mu)}
/* Fontes e método */
#hmt-radar .rd-como{margin-top:18px;border:1px solid var(--bd);border-radius:14px;background:var(--card);padding:0 14px}
#hmt-radar .rd-como>summary{cursor:pointer;font-weight:750;padding:14px 0;color:var(--tx)}
#hmt-radar .rd-como>summary small{font-weight:400;color:var(--mu);margin-left:6px}
#hmt-radar .rd-como h4{margin:14px 0 6px;font-size:.95rem;color:var(--tx)}
#hmt-radar .rd-como p,#hmt-radar .rd-como li{font-size:.88rem;color:var(--tx2)}
#hmt-radar .rd-como ul{padding-left:18px;margin:6px 0}
#hmt-radar .rd-como a{color:var(--acao)}
@media (prefers-color-scheme:dark){html:not([data-theme="light"]) #hmt-radar .rd-como a{color:var(--foco)}}
html[data-theme="dark"] #hmt-radar .rd-como a{color:var(--foco)}
#hmt-radar .rd-veics{columns:2;column-gap:20px;font-size:.84rem;color:var(--tx2);padding-left:18px}
